(function () {
  const { G, R, CI, PA, TX, J, hash } = BM, tl = () => BM.tl;
  const CAM = (BM.CAM = {}), TR = (BM.TR = {}), CAP = (BM.CAP = {});
  let OV, SUB; const overlay = () => (OV ||= G({ 'data-name': 'overlay', 'pointer-events': 'none' }));
