  /* ---------------- camera moves ---------------- */
  CAM.push = (sc, at, z, dur = 2, ease = 'sine.inOut') => tl().to(sc.cam, { z, duration: dur, ease, onUpdate: sc.apply }, at);
  CAM.pan = (sc, at, x, y, dur = 1.6, ease = 'power2.inOut') => tl().to(sc.cam, { x, y, duration: dur, ease, onUpdate: sc.apply }, at);
