1	/* world.js — environments + props for Motion Studio (needs bm-core.js). Vertical-first (1080x1920 stage),
2	   every environment draws into a stage group, registers its own ambient motion (clocks, lights, clouds, traffic,
3	   steam — all closed-form functions of t) and returns anchors (floor y, desk top, seats, doors) for staging.
4	   Palette comes from opts.pal (style packs pass theirs); defaults are the flat-cartoon palette.
5	   Props: PROP.<name>(parent, x, y, scale, opts) -> { g, j (joint), ...parts }. */
6	(function () {
7	  const { G, R, CI, EL, PA, LN, TX, J, shade, hash } = BM;
8	  const ENV = (BM.ENV = {}), PROP = (BM.PROP = {});
9	  const PAL = { ink: '#1E1B2E', wall: '#F3E6CF', wall2: '#E8D6B8', floor: '#B98B63', floor2: '#A57A54', wood: '#8A5A3A', wood2: '#6B4329',
10	    sky: '#9ED8F2', sky2: '#E3F4FB', grass: '#7DC67E', metal: '#9AA3B5', glass: '#BFE6F7', accent: '#4C7DFF', accent2: '#FF7A59', gold: '#FFC83D', night: '#1E2244' };
11	  const P = o => ({ ...PAL, ...(o && o.pal) });
12	  const tick = fn => BM.everyFrame(fn);
13	
14	  /* ================= PROPS ================= */
15	  PROP.desk = (p, x, y, s = 1, o = {}) => { const c = P(o), g = G({ transform: `translate(${x},${y}) scale(${s})` }, p);
16	    R(-260, -18, 520, 36, c.wood, 8, g); R(-240, 18, 30, 220, c.wood2, 4, g); R(210, 18, 30, 220, c.wood2, 4, g); R(-200, 18, 160, 120, shade(c.wood2, 1.1), 6, g); R(-150, 70, 60, 10, '#E8D2B5', 5, g); return { g, top: y - 18 * s }; };
17	  PROP.monitor = (p, x, y, s = 1, o = {}) => { const g = G({ transform: `translate(${x},${y}) scale(${s})` }, p);
18	    R(-30, -24, 60, 24, '#2B2E3A', 4, g); R(-10, -90, 20, 70, '#2B2E3A', 0, g); R(-150, -280, 300, 200, '#20232E', 14, g); const screen = G({}, g);
19	    R(-138, -268, 276, 176, o.screen || '#3E7BFF', 6, screen); return { g, screen, sx: x, sy: y - 180 * s }; };
