40	  PROP.coin = (p, x, y, s = 1) => { const g = G({ transform: `translate(${x},${y}) scale(${s})` }, p), j = J(G({}, g)); CI(0, 0, 22, '#FFC83D', j.el, { stroke: '#E29A00', 'stroke-width': 4 }); TX(0, 9, '$', 24, '#B87400', j.el, { 'font-weight': 900 }); return { g, j }; };
41	  PROP.car = (p, x, y, s = 1, o = {}) => { const col = o.color || '#E63946', g = G({ transform: `translate(${x},${y}) scale(${s})` }, p), j = J(G({}, g));
