    maya:  { name: 'Maya',  role: 'designer',             skin: '#C98E66', hair: ['bob', '#1E1414'], top: ['tshirt', '#FF7A59'], pants: '#2B3A55', shoes: '#FFFFFF', acc: ['glasses', 'earrings'] },
