    for (let i = 0; i < n; i++) { const syl = Math.floor(i * rate / 30); fr.push(BM.hash(syl * 7.3 + ch.x) < .18 ? 0 : 1 + Math.floor(BM.hash(syl * 3.1 + ch.gy) * 4)); }
