+BM.STYLE.use('cartoon');
+const tl = BM.tl;
+
+/* dialogue: real timings from tools/voice.py (fallbacks keep the page alive without the voice step) */
+const FALLBACK = [['omar', 'Morning, Dave.', 2.7, 3.5], ['dave', 'Crunching numbers, boss!', 4.0, 5.1], ['omar', 'Deep in thought?', 12.6, 13.4],
+  ['dave', 'Visualizing synergy.', 14.0, 15.1], ['omar', 'Dave. Your monitor is off.', 20.8, 22.3], ['dave', "It's a power saving spreadsheet.", 22.9, 24.4], ['omar', 'Crunching numbers, sir!', 26.2, 27.35]]
+  .map(([who, text, t0, t1]) => ({ who, text, t0, t1 }));
