+const bounce = (ch, t0, n, amp = 6) => tl.fromTo(ch.root, { y: 0 }, { y: -amp, duration: .12, ease: 'sine.inOut', yoyo: true, repeat: n * 2 - 1, onUpdate: ch.root.apply, immediateRender: false }, t0);
+
+/* ================= STAGE A: the office ================= */
