+  const cj = J(G({}, g), 0, -176);
+  PA('M -44 -30 L -36 -78 L -8 -44 Z', '#F2A65A', cj.el); PA('M 44 -30 L 36 -78 L 8 -44 Z', '#F2A65A', cj.el);
