+const SCREENS = { cat, sheet, off };
+const screen = (at, name) => { for (const k in SCREENS) tl.set(SCREENS[k], { opacity: k === name ? 1 : 0 }, at); tl.set(led, { attr: { fill: name === 'off' ? '#E63946' : '#3BD16F' } }, at); };
+
+Object.assign(A.cam, { x: 640, y: 1330, z: 1.55 }); A.apply(); BM.cut(0, null, A);
+CH.idle(omar, 0, DUR); CH.idle(rex, 0, DUR);
+
+/* ---------- GAG 1 (9:00 AM): cat video -> fake typing ---------- */
